module apbxclk #(
  parameter C_APB_ADDR_WIDTH = 12,
  parameter C_APB_DATA_WIDTH = 32,
  parameter [0:0] OPT_REGISTERED = 1'b0
)(
  input  wire                         S_APB_PCLK,
  input  wire                         S_PRESETn,
  input  wire                         S_APB_PSEL,
  input  wire                         S_APB_PENABLE,
  output reg                          S_APB_PREADY,
  input  wire [C_APB_ADDR_WIDTH-1:0]  S_APB_PADDR,
  input  wire                         S_APB_PWRITE,
  input  wire [C_APB_DATA_WIDTH-1:0]  S_APB_PWDATA,
  input  wire [C_APB_DATA_WIDTH/8-1:0] S_APB_PWSTRB,
  input  wire [2:0]                   S_APB_PPROT,
  output wire [C_APB_DATA_WIDTH-1:0]  S_APB_PRDATA,
  output wire                         S_APB_PSLVERR,

  input  wire                         M_APB_PCLK,
  output reg                          M_PRESETn,
  output reg                          M_APB_PSEL,
  output reg                          M_APB_PENABLE,
  input  wire                         M_APB_PREADY,
  output reg  [C_APB_ADDR_WIDTH-1:0]  M_APB_PADDR,
  output reg                          M_APB_PWRITE,
  output reg  [C_APB_DATA_WIDTH-1:0]  M_APB_PWDATA,
  output reg  [C_APB_DATA_WIDTH/8-1:0] M_APB_PWSTRB,
  output reg  [2:0]                   M_APB_PPROT,
  input  wire [C_APB_DATA_WIDTH-1:0]  M_APB_PRDATA,
  input  wire                         M_APB_PSLVERR
);

  reg [C_APB_ADDR_WIDTH-1:0]  s_addr;
  reg                         s_write;
  reg [C_APB_DATA_WIDTH-1:0]  s_wdata;
  reg [C_APB_DATA_WIDTH/8-1:0] s_wstrb;
  reg [2:0]                   s_prot;
  reg                         s_valid;
  reg                         m_valid;
  reg                         m_ready;
  reg [C_APB_DATA_WIDTH-1:0]  rdata;
  reg                         slverr;

  assign M_PRESETn = S_PRESETn;

  always @(posedge S_APB_PCLK or negedge S_PRESETn) begin
    if (!S_PRESETn) begin
      S_APB_PREADY <= 1'b0;
      s_valid <= 1'b0;
      s_addr <= {C_APB_ADDR_WIDTH{1'b0}};
      s_write <= 1'b0;
      s_wdata <= {C_APB_DATA_WIDTH{1'b0}};
      s_wstrb <= {C_APB_DATA_WIDTH/8{1'b0}};
      s_prot <= {3{1'b0}};
    end else if (S_APB_PSEL &&!S_APB_PENABLE) begin
      s_valid <= 1'b1;
      s_addr <= S_APB_PADDR;
      s_write <= S_APB_PWRITE;
      s_wdata <= S_APB_PWDATA;
      s_wstrb <= S_APB_PWSTRB;
      s_prot <= S_APB_PPROT;
    end else if (S_APB_PSEL && S_APB_PENABLE && S_APB_PREADY) begin
      s_valid <= 1'b0;
    end
  end

  always @(posedge M_APB_PCLK or negedge M_PRESETn) begin
    if (!M_PRESETn) begin
      M_APB_PSEL <= 1'b0;
      M_APB_PENABLE <= 1'b0;
      m_valid <= 1'b0;
      m_ready <= 1'b0;
      M_APB_PADDR <= {C_APB_ADDR_WIDTH{1'b0}};
      M_APB_PWRITE <= 1'b0;
      M_APB_PWDATA <= {C_APB_DATA_WIDTH{1'b0}};
      M_APB_PWSTRB <= {C_APB_DATA_WIDTH/8{1'b0}};
      M_APB_PPROT <= {3{1'b0}};
    end else if (s_valid &&!m_valid) begin
      M_APB_PSEL <= 1'b1;
      M_APB_PENABLE <= 1'b0;
      m_valid <= 1'b1;
      M_APB_PADDR <= s_addr;
      M_APB_PWRITE <= s_write;
      M_APB_PWDATA <= s_wdata;
      M_APB_PWSTRB <= s_wstrb;
      M_APB_PPROT <= s_prot;
    end else if (m_valid &&!M_APB_PREADY) begin
      M_APB_PENABLE <= 1'b1;
    end else if (m_valid && M_APB_PREADY) begin
      M_APB_PSEL <= 1'b0;
      M_APB_PENABLE <= 1'b0;
      m_valid <= 1'b0;
      m_ready <= 1'b1;
      rdata <= M_APB_PRDATA;
      slverr <= M_APB_PSLVERR;
    end else if (m_ready) begin
      m_ready <= 1'b0;
    end
  end

  always @(posedge S_APB_PCLK) begin
    if (m_ready) begin
      S_APB_PREADY <= 1'b1;
    end else begin
      S_APB_PREADY <= 1'b0;
    end
  end

  generate
    if (OPT_REGISTERED) begin
      reg [C_APB_DATA_WIDTH-1:0] rdata_reg;
      reg                         slverr_reg;

      always @(posedge M_APB_PCLK) begin
        rdata_reg <= M_APB_PRDATA;
        slverr_reg <= M_APB_PSLVERR;
      end

      assign S_APB_PRDATA = m_ready ? rdata : {C_APB_DATA_WIDTH{1'b0}};
      assign S_APB_PSLVERR = m_ready ? slverr : 1'b0;
    end else begin
      assign S_APB_PRDATA = m_ready ? M_APB_PRDATA : {C_APB_DATA_WIDTH{1'b0}};
      assign S_APB_PSLVERR = m_ready ? M_APB_PSLVERR : 1'b0;
    end
  endgenerate

endmodule
